{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C27"],
      "claim": "Lamivudine, a polar nucleoside analogue with an amino-substituted pyrimidinone, showed absolute oral bioavailability of 68.6 ± 11% in fasted HIV patients, directly supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "Zalcitabine (ddC), another small polar nucleoside with an amino-substituted pyrimidinone, was approximately 70–90% bioavailable after oral administration in patients, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C56"],
      "claim": "Sodium saccharin, a small polar cyclic imide/sulfonamide, had a fasted fraction absorbed of 0.88 ± 0.02 versus IV in healthy volunteers, supporting high oral bioavailability for a small polar lactam-like molecule.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C28"],
      "claim": "Ondansetron, a moderately polar heterocyclic drug, showed ~85% absolute oral bioavailability in subjects with cancer, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C59"],
      "claim": "Milvexian, a complex oral drug, showed ~100% absolute bioavailability under fasted conditions when given as an oral solution, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C39"],
      "claim": "Apixaban, a larger oral drug with incomplete absorption, still has about 50% absolute oral bioavailability, well above the 20% threshold, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Fenspiride, a small basic drug, showed 90% absolute oral bioavailability in healthy volunteers, supporting high F.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All high-transfer experimental analogues report absolute oral bioavailability values well above the 20% threshold (approximately 44–100%), with no contradictory low-F evidence; therefore the query is predicted high.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query molecule itself; prediction relies on high-transfer analogues.",
    "Some retrieved records report extent of absorption rather than strictly absolute bioavailability, but all values remain above the threshold."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

